"use strict";

var EventEmitter = require('events').EventEmitter;
var Logger = require('./Logger');
var CRTC_C = require('./Constants');
var Registrator = require('./Registrator');
var RTCSession = require('./RTCSession');
var Message = require('./Message');
var Options = require('./Options');
var Transactions = require('./Transactions');
var Transport = require('./Transport');
var Utils = require('./Utils');
var Exceptions = require('./Exceptions');
var URI = require('./URI');
var Parser = require('./Parser');
var SIPMessage = require('./SIPMessage');
var sanityCheck = require('./sanityCheck');
var config = require('./Config');
var encrypt = require('jsencrypt');
var cryptoKey = require('./CryptoKey');
var logger = new Logger('UA');
var C = {
  // UA status codes.
  STATUS_INIT: 0,
  STATUS_READY: 1,
  STATUS_USER_CLOSED: 2,
  STATUS_NOT_READY: 3,
  // UA error codes.
  CONFIGURATION_ERROR: 1,
  NETWORK_ERROR: 2
};

// 授权码
var sk;

// 生成当前年月日字符串
function generateDate() {
  var myDate = new Date();
  var tYear = myDate.getFullYear();
  var tMonth = myDate.getMonth();
  var tDate = myDate.getDate();
  var m = tMonth + 1;
  if (m.toString().length == 1) {
    m = `0${m}`;
  }
  var d = tDate;
  if (d.toString().length == 1) {
    d = `0${d}`;
  }
  return `${tYear}${m}${d}`;
}

/**
 * The User-Agent class.
 * @class CRTC.UA
 * @param {Object} configuration Configuration parameters.
 * @throws {CRTC.Exceptions.ConfigurationError} If a configuration parameter is invalid.
 * @throws {TypeError} If no configuration is given.
 */
module.exports = class UA extends EventEmitter {
  // Expose C object.
  static get C() {
    return C;
  }
  constructor(configuration) {
    logger.debug('new() [configuration:%o]', configuration);
    logger.debug(`new() [configuration: ${JSON.stringify(configuration)}]`);

    // 设备列表变化
    navigator.mediaDevices.addEventListener('devicechange', () => {
      logger.warn('devicechange');
    });
    super();
    this._cache = {
      credentials: {}
    };

    // 生成当前日期
    this._date = generateDate();
    this._configuration = Object.assign({}, config.settings);
    this._dynConfiguration = {};
    this._dialogs = {};

    // User actions outside any session/dialog (MESSAGE/OPTIONS).
    this._applicants = {};
    this._sessions = {};
    this._transport = null;
    this._contact = null;
    this._status = C.STATUS_INIT;
    this._error = null;
    this._transactions = {
      nist: {},
      nict: {},
      ist: {},
      ict: {}
    };

    // Custom UA empty object for high level use.
    this._data = {};
    this._closeTimer = null;

    // Check configuration argument.
    if (configuration === undefined || configuration.secret_key === undefined) {
      throw new TypeError('Not enough arguments');
    }

    // 当前选项卡可见状态切换事件日志
    try {
      document.addEventListener('visibilitychange', function () {
        logger.debug(`document visibility change to ${document.visibilityState}, ${document.hidden}`);
      });
    } catch (error) {}

    // 解析授权码
    try {
      var je = new encrypt.JSEncrypt();
      je.setPublicKey(cryptoKey);
      sk = je.decrypt(configuration.secret_key, false).replace(/\s*/g, '').split('|');
      if (sk && sk[2] <= generateDate()) {
        sk[2] = 1;
      } else {
        sk[2] = 0;
      }
      if (sk && generateDate() <= sk[3]) {
        sk[3] = 1;
      } else {
        sk[3] = 0;
      }
      if (sk[0] == '00') {
        sk[0] = true;
      } else {
        sk[0] = false;
      }
      if (sk[10] == '2') {
        sk[10] = true;
      } else {
        sk[10] = false;
      }
    } catch (error) {
      sk = 'decrypt_error';
    }

    // Load configuration.
    try {
      this._loadConfig(configuration);
    } catch (e) {
      this._status = C.STATUS_NOT_READY;
      this._error = C.CONFIGURATION_ERROR;
      throw e;
    }

    // Initialize registrator.
    this._registrator = new Registrator(this);

    // 监听本地网络状态
    window.addEventListener('offline', e => {
      this.emit('browser:navigator:offline', e);
    });
    window.addEventListener('online', e => {
      this.emit('browser:navigator:online', e);
    });
  }
  get C() {
    return C;
  }

  // 提供解析后的授权码
  get sk() {
    return sk;
  }
  get status() {
    return this._status;
  }
  get contact() {
    return this._contact;
  }
  get configuration() {
    return this._configuration;
  }
  get transport() {
    return this._transport;
  }

  // =================
  //  High Level API
  // =================

  /**
   * Connect to the server if status = STATUS_INIT.
   * Resume UA after being closed.
   */
  start() {
    logger.debug('start()');
    if (this._status === C.STATUS_INIT) {
      if (!sk) {
        return;
      }
      if (sk === 'decrypt_error') {
        this.emit('failed', {
          originator: 'local',
          message: CRTC_C.causes.AUTHORIZATION_ERROR,
          cause: CRTC_C.AUTHORIZATION_ERROR_CAUSES.AUTH_DECRYPT_ERROR
        });
        return;
      }
      if (!sk[0]) {
        this.emit('failed', {
          originator: 'local',
          message: CRTC_C.causes.AUTHORIZATION_ERROR,
          cause: CRTC_C.AUTHORIZATION_ERROR_CAUSES.AUTH_PRODUCT_ID_ERROR
        });
        return;
      }
      if (!sk[10]) {
        this.emit('failed', {
          originator: 'local',
          message: CRTC_C.causes.AUTHORIZATION_ERROR,
          cause: CRTC_C.AUTHORIZATION_ERROR_CAUSES.AUTH_PLATFORMID_ERROR
        });
        return;
      }
      if (!sk[2]) {
        this.emit('failed', {
          originator: 'local',
          message: CRTC_C.causes.AUTHORIZATION_ERROR,
          cause: CRTC_C.AUTHORIZATION_ERROR_CAUSES.AUTH_STARTTIME_ERROR
        });
        return;
      }
      if (!sk[3]) {
        this.emit('failed', {
          originator: 'local',
          message: CRTC_C.causes.AUTHORIZATION_ERROR,
          cause: CRTC_C.AUTHORIZATION_ERROR_CAUSES.AUTH_ENDTIME_ERROR
        });
        return;
      }

      // 判断授权的 sip domain
      if (sk[8].indexOf(this._configuration.uri.host) != -1) {
        // eslint-disable-next-line no-useless-escape
        var sipproxy = this.transport.url.match(/(([a-zA-Z0-9\-]*\.{1,}){1,}[a-zA-Z0-9]*)/g);
        if (sk[9].indexOf(sipproxy) != -1) {
          this._transport.connect();

          // 开始连接5秒后，如果未连接成功则触发failed事件
          setTimeout(() => {
            if (!this.isConnected()) {
              this.emit('connectFailed', {
                originator: 'local',
                message: CRTC_C.causes.CONNECTION_ERROR
              });
            }
          }, 5000);
        } else {
          this.emit('failed', {
            originator: 'local',
            message: CRTC_C.causes.AUTHORIZATION_ERROR,
            cause: CRTC_C.AUTHORIZATION_ERROR_CAUSES.AUTH_SIPPROXY_ERROR
          });
          return false;
        }
      } else {
        this.emit('failed', {
          originator: 'local',
          message: CRTC_C.causes.AUTHORIZATION_ERROR,
          cause: CRTC_C.AUTHORIZATION_ERROR_CAUSES.AUTH_SIPDOMAIN_ERROR
        });
        return;
      }
    } else if (this._status === C.STATUS_USER_CLOSED) {
      logger.debug('restarting UA');

      // Disconnect.
      if (this._closeTimer !== null) {
        clearTimeout(this._closeTimer);
        this._closeTimer = null;
        this._transport.disconnect();
      }

      // Reconnect.
      this._status = C.STATUS_INIT;
      this._transport.connect();
    } else if (this._status === C.STATUS_READY) {
      logger.debug('UA is in READY status, not restarted');
    } else {
      logger.debug('ERROR: connection is down, Auto-Recovery system is trying to reconnect');
    }

    // Set dynamic configuration.
    this._dynConfiguration.register = this._configuration.register;
  }

  /**
   * Register.
   */
  register() {
    logger.debug('register()');
    this._dynConfiguration.register = true;
    this._registrator.register();
  }

  /**
   * Unregister.
   */
  unregister(options) {
    logger.debug('unregister()');
    this._dynConfiguration.register = false;
    this._registrator.unregister(options);
  }

  /**
   * Get the Registrator instance.
   */
  registrator() {
    return this._registrator;
  }

  /**
   * Registration state.
   */
  isRegistered() {
    return this._registrator.registered;
  }

  /**
   * Connection state.
   */
  isConnected() {
    return this._transport.isConnected();
  }

  /**
   * Make an outgoing call.
   *
   * -param {String} target
   * -param {Object} [options]
   *
   * -throws {TypeError}
   *
   */
  call(target, options) {
    logger.debug(`call() target:${target} options:${JSON.stringify(options)}`);

    // 初始化统计信息参数
    window.CRTCStats = 'start';
    var session = new RTCSession(this);
    return session.connect(target, options).then(() => {
      return session;
    });
  }

  /**
   * Send a message.
   *
   * -param {String} target
   * -param {String} body
   * -param {Object} [options]
   *
   * -throws {TypeError}
   *
   */
  sendMessage(target, body, options) {
    logger.debug('sendMessage()');
    var message = new Message(this);
    message.send(target, body, options);
    return message;
  }

  /**
   * Send a SIP OPTIONS.
   *
   * -param {String} target
   * -param {String} [body]
   * -param {Object} [options]
   *
   * -throws {TypeError}
   *
   */
  sendOptions(target, body, options) {
    logger.debug('sendOptions()');
    var message = new Options(this);
    message.send(target, body, options);
    return message;
  }

  /**
   * Terminate ongoing sessions.
   */
  terminateSessions(options) {
    logger.debug('terminateSessions()');
    for (var idx in this._sessions) {
      if (!this._sessions[idx].isEnded()) {
        this._sessions[idx].terminate(options);
      }
    }
  }

  /**
   * Gracefully close.
   *
   */
  stop() {
    logger.debug('stop()');

    // Remove dynamic settings.
    this._dynConfiguration = {};
    if (this._status === C.STATUS_USER_CLOSED) {
      logger.debug('UA already closed');
      return;
    }

    // Close registrator.
    this._registrator.close();

    // If there are session wait a bit so CANCEL/BYE can be sent and their responses received.
    var num_sessions = Object.keys(this._sessions).length;

    // Run  _terminate_ on every Session.
    for (var session in this._sessions) {
      if (Object.prototype.hasOwnProperty.call(this._sessions, session)) {
        logger.debug(`closing session ${session}`);
        try {
          this._sessions[session].terminate();
        } catch (error) {}
      }
    }

    // Run  _close_ on every applicant.
    for (var applicant in this._applicants) {
      if (Object.prototype.hasOwnProperty.call(this._applicants, applicant)) try {
        this._applicants[applicant].close();
      } catch (error) {}
    }
    this._status = C.STATUS_USER_CLOSED;
    var num_transactions = Object.keys(this._transactions.nict).length + Object.keys(this._transactions.nist).length + Object.keys(this._transactions.ict).length + Object.keys(this._transactions.ist).length;
    if (num_transactions === 0 && num_sessions === 0) {
      this._transport.disconnect();
    } else {
      this._closeTimer = setTimeout(() => {
        this._closeTimer = null;
        this._transport.disconnect();
      }, 2000);
    }
  }

  /**
   * Normalice a string into a valid SIP request URI
   * -param {String} target
   * -returns {CRTC.URI|undefined}
   */
  normalizeTarget(target) {
    return Utils.normalizeTarget(target, this._configuration.hostport_params);
  }

  /**
   * Allow retrieving configuration and autogenerated fields in runtime.
   */
  get(parameter) {
    switch (parameter) {
      case 'authorization_user':
        return this._configuration.authorization_user;
      case 'realm':
        return this._configuration.realm;
      case 'ha1':
        return this._configuration.ha1;
      case 'authorization_jwt':
        return this._configuration.authorization_jwt;
      default:
        logger.warn('get() | cannot get "%s" parameter in runtime', parameter);
        return undefined;
    }
  }

  /**
   * Allow configuration changes in runtime.
   * Returns true if the parameter could be set.
   */
  set(parameter, value) {
    switch (parameter) {
      case 'authorization_user':
        {
          this._configuration.authorization_user = String(value);
          break;
        }
      case 'password':
        {
          this._configuration.password = String(value);
          break;
        }
      case 'realm':
        {
          this._configuration.realm = String(value);
          break;
        }
      case 'ha1':
        {
          this._configuration.ha1 = String(value);
          // Delete the plain SIP password.
          this._configuration.password = null;
          break;
        }
      case 'authorization_jwt':
        {
          this._configuration.authorization_jwt = String(value);
          break;
        }
      case 'display_name':
        {
          this._configuration.display_name = value;
          break;
        }

      // 新增可修改via_host
      case 'via_host':
        {
          this._configuration.via_host = value;
          this._configuration.contact_uri = new URI('sip', this._configuration.uri.user, this._configuration.via_host, null, {
            transport: 'ws'
          });
          this._contact.uri = this._configuration.contact_uri;
          break;
        }
      default:
        logger.warn('set() | cannot set "%s" parameter in runtime', parameter);
        return false;
    }
    return true;
  }

  // ==========================
  // Event Handlers.
  // ==========================

  /**
   * new Transaction
   */
  newTransaction(transaction) {
    this._transactions[transaction.type][transaction.id] = transaction;
    this.emit('newTransaction', {
      transaction
    });
  }

  /**
   * Transaction destroyed.
   */
  destroyTransaction(transaction) {
    delete this._transactions[transaction.type][transaction.id];
    this.emit('transactionDestroyed', {
      transaction
    });
  }

  /**
   * new Dialog
   */
  newDialog(dialog) {
    this._dialogs[dialog.id] = dialog;
  }

  /**
   * Dialog destroyed.
   */
  destroyDialog(dialog) {
    delete this._dialogs[dialog.id];
  }

  /**
   *  new Message
   */
  newMessage(message, data) {
    this._applicants[message] = message;
    this.emit('newMessage', data);
  }

  /**
   *  new Options
   */
  newOptions(message, data) {
    this._applicants[message] = message;
    this.emit('newOptions', data);
  }

  /**
   *  Message destroyed.
   */
  destroyMessage(message) {
    delete this._applicants[message];
  }

  /**
   * new RTCSession
   */
  newRTCSession(session, data) {
    this._sessions[session.id] = session;
    this.emit('newRTCSession', data);
  }

  /**
   * RTCSession destroyed.
   */
  destroyRTCSession(session) {
    delete this._sessions[session.id];
  }

  /**
   * Registered
   */
  registered(data) {
    this.emit('registered', data);
  }

  /**
   * Unregistered
   */
  unregistered(data) {
    this.emit('unregistered', data);
  }

  /**
   * Registration Failed
   */
  registrationFailed(data) {
    this.emit('registrationFailed', data);
  }

  // =========================
  // ReceiveRequest.
  // =========================

  /**
   * Request reception
   */
  receiveRequest(request) {
    var method = request.method;

    // Check that request URI points to us.
    if (request.ruri.user !== this._configuration.uri.user && request.ruri.user !== this._contact.uri.user) {
      logger.debug('Request-URI does not point to us');
      if (request.method !== CRTC_C.ACK) {
        request.reply_sl(404);
      }
      return;
    }

    // Check request URI scheme.
    if (request.ruri.scheme === CRTC_C.SIPS) {
      request.reply_sl(416);
      return;
    }

    // Check transaction.
    if (Transactions.checkTransaction(this, request)) {
      return;
    }

    // Create the server transaction.
    if (method === CRTC_C.INVITE) {
      /* eslint-disable no-new */
      new Transactions.InviteServerTransaction(this, this._transport, request);
      /* eslint-enable no-new */
    } else if (method !== CRTC_C.ACK && method !== CRTC_C.CANCEL) {
      /* eslint-disable no-new */
      new Transactions.NonInviteServerTransaction(this, this._transport, request);
      /* eslint-enable no-new */
    }

    /* RFC3261 12.2.2
     * Requests that do not change in any way the state of a dialog may be
     * received within a dialog (for example, an OPTIONS request).
     * They are processed as if they had been received outside the dialog.
     */
    if (method === CRTC_C.OPTIONS) {
      if (this.listeners('newOptions').length === 0) {
        request.reply(200);
        return;
      }
      var message = new Options(this);
      message.init_incoming(request);
    } else if (method === CRTC_C.MESSAGE) {
      if (this.listeners('newMessage').length === 0) {
        request.reply(405);
        return;
      }
      var _message = new Message(this);
      _message.init_incoming(request);
    } else if (method === CRTC_C.INVITE) {
      // Initial INVITE.
      if (!request.to_tag && this.listeners('newRTCSession').length === 0) {
        request.reply(405);
        return;
      }
    }
    var dialog;
    var session;

    // Initial Request.
    if (!request.to_tag) {
      switch (method) {
        case CRTC_C.INVITE:
          if (window.RTCPeerConnection) {
            // TODO
            if (request.hasHeader('replaces')) {
              var replaces = request.replaces;
              dialog = this._findDialog(replaces.call_id, replaces.from_tag, replaces.to_tag);
              if (dialog) {
                session = dialog.owner;
                if (!session.isEnded()) {
                  session.receiveRequest(request);
                } else {
                  request.reply(603);
                }
              } else {
                request.reply(481);
              }
            } else {
              session = new RTCSession(this);
              session.init_incoming(request);
            }
          } else {
            logger.warn('INVITE received but WebRTC is not supported');
            request.reply(488);
          }
          break;
        case CRTC_C.BYE:
          // Out of dialog BYE received.
          request.reply(481);
          break;
        case CRTC_C.CANCEL:
          session = this._findSession(request);
          if (session) {
            session.receiveRequest(request);
          } else {
            logger.debug('received CANCEL request for a non existent session');
          }
          break;
        case CRTC_C.ACK:
          /* Absorb it.
           * ACK request without a corresponding Invite Transaction
           * and without To tag.
           */
          break;
        case CRTC_C.NOTIFY:
          // Receive new sip event.
          this.emit('sipEvent', {
            event: request.event,
            request
          });
          request.reply(200);
          break;
        default:
          request.reply(405);
          break;
      }
    }
    // In-dialog request.
    else {
      dialog = this._findDialog(request.call_id, request.from_tag, request.to_tag);
      if (dialog) {
        dialog.receiveRequest(request);
      } else if (method === CRTC_C.NOTIFY) {
        session = this._findSession(request);
        if (session) {
          session.receiveRequest(request);
        } else {
          logger.debug('received NOTIFY request for a non existent subscription');
          request.reply(481, 'Subscription does not exist');
        }
      }

      /* RFC3261 12.2.2
       * Request with to tag, but no matching dialog found.
       * Exception: ACK for an Invite request for which a dialog has not
       * been created.
       */else if (method !== CRTC_C.ACK) {
        request.reply(481);
      }
    }
  }

  // =================
  // Utils.
  // =================

  /**
   * Get the session to which the request belongs to, if any.
   */
  _findSession({
    call_id,
    from_tag,
    to_tag
  }) {
    var sessionIDa = call_id + from_tag;
    var sessionA = this._sessions[sessionIDa];
    var sessionIDb = call_id + to_tag;
    var sessionB = this._sessions[sessionIDb];
    if (sessionA) {
      return sessionA;
    } else if (sessionB) {
      return sessionB;
    } else {
      return null;
    }
  }

  /**
   * Get the dialog to which the request belongs to, if any.
   */
  _findDialog(call_id, from_tag, to_tag) {
    var id = call_id + from_tag + to_tag;
    var dialog = this._dialogs[id];
    if (dialog) {
      return dialog;
    } else {
      id = call_id + to_tag + from_tag;
      dialog = this._dialogs[id];
      if (dialog) {
        return dialog;
      } else {
        return null;
      }
    }
  }
  _loadConfig(configuration) {
    // Check and load the given configuration.
    try {
      config.load(this._configuration, configuration);
    } catch (e) {
      throw e;
    }

    // Post Configuration Process.

    // Allow passing 0 number as display_name.
    if (this._configuration.display_name === 0) {
      this._configuration.display_name = '0';
    }

    // Instance-id for GRUU.
    if (!this._configuration.instance_id) {
      this._configuration.instance_id = Utils.newUUID();
    }

    // Crtc_id instance parameter. Static random tag of length 5.
    this._configuration.crtc_id = Utils.createRandomToken(5);

    // String containing this._configuration.uri without scheme and user.
    var hostport_params = this._configuration.uri.clone();
    hostport_params.user = null;
    this._configuration.hostport_params = hostport_params.toString().replace(/^sip:/i, '');

    // Transport.
    try {
      this._transport = new Transport(this._configuration.sockets, {
        // Recovery options.
        max_interval: this._configuration.connection_recovery_max_interval,
        min_interval: this._configuration.connection_recovery_min_interval
      });

      // Transport event callbacks.
      this._transport.onconnecting = onTransportConnecting.bind(this);
      this._transport.onconnect = onTransportConnect.bind(this);
      this._transport.ondisconnect = onTransportDisconnect.bind(this);
      this._transport.ondata = onTransportData.bind(this);
    } catch (e) {
      logger.warn(e);
      throw new Exceptions.ConfigurationError('sockets', this._configuration.sockets);
    }

    // Remove sockets instance from configuration object.
    delete this._configuration.sockets;

    // Check whether authorization_user is explicitly defined.
    // Take 'this._configuration.uri.user' value if not.
    if (!this._configuration.authorization_user) {
      this._configuration.authorization_user = this._configuration.uri.user;
    }

    // If no 'registrar_server' is set use the 'uri' value without user portion and
    // without URI params/headers.
    if (!this._configuration.registrar_server) {
      var registrar_server = this._configuration.uri.clone();
      registrar_server.user = null;
      registrar_server.clearParams();
      registrar_server.clearHeaders();
      this._configuration.registrar_server = registrar_server;
    }

    // User no_answer_timeout.
    this._configuration.no_answer_timeout *= 1000;

    // Via Host.
    if (this._configuration.contact_uri) {
      this._configuration.via_host = this._configuration.contact_uri.host;
    }

    // Contact URI.
    else {
      // 兼容SBC Contact URI默认用户id设置为SIP URI里面的用户名
      this._configuration.contact_uri = new URI('sip', this._configuration.uri.user, this._configuration.via_host, null, {
        transport: 'ws'
      });
    }
    this._contact = {
      pub_gruu: null,
      temp_gruu: null,
      uri: this._configuration.contact_uri,
      toString(options = {}) {
        var anonymous = options.anonymous || null;
        var outbound = options.outbound || null;
        var contact = '<';
        if (anonymous) {
          contact += this.temp_gruu || 'sip:anonymous@anonymous.invalid;transport=ws';
        } else {
          contact += this.pub_gruu || this.uri.toString();
        }
        if (outbound && (anonymous ? !this.temp_gruu : !this.pub_gruu)) {
          contact += ';ob';
        }

        // 5G contact
        if (sk[7] >= 3) {
          contact += '>;audio;video;+g.3gpp.icsi-ref="urn%3Aurn-7%3A3gpp-service.ims.icsi.mmtel"';
        } else {
          contact += '>';
        }
        return contact;
      }
    };

    // Seal the configuration.
    var writable_parameters = ['authorization_user', 'password', 'realm', 'ha1', 'authorization_jwt', 'display_name', 'register', 'via_host', 'contact_uri'];
    for (var parameter in this._configuration) {
      if (Object.prototype.hasOwnProperty.call(this._configuration, parameter)) {
        if (writable_parameters.indexOf(parameter) !== -1) {
          Object.defineProperty(this._configuration, parameter, {
            writable: true,
            configurable: false
          });
        } else {
          Object.defineProperty(this._configuration, parameter, {
            writable: false,
            configurable: false
          });
        }
      }
    }
    logger.debug('configuration parameters after validation:');
    for (var _parameter in this._configuration) {
      // Only show the user user configurable parameters.
      if (Object.prototype.hasOwnProperty.call(config.settings, _parameter)) {
        switch (_parameter) {
          case 'uri':
          case 'registrar_server':
            logger.debug(`- ${_parameter}: ${this._configuration[_parameter]}`);
            break;
          case 'password':
          case 'ha1':
          case 'authorization_jwt':
            logger.debug(`- ${_parameter}: NOT SHOWN`);
            break;
          default:
            logger.debug(`- ${_parameter}: ${JSON.stringify(this._configuration[_parameter])}`);
        }
      }
    }
    return;
  }
};

/**
 * Transport event handlers
 */

// Transport connecting event.
function onTransportConnecting(data) {
  this.emit('connecting', data);
}

// Transport connected event.
function onTransportConnect(data) {
  if (this._status === C.STATUS_USER_CLOSED) {
    return;
  }
  this._status = C.STATUS_READY;
  this._error = null;
  this.emit('connected', data);
  if (this._dynConfiguration.register) {
    this._registrator.register();
  }
}

// Transport disconnected event.
function onTransportDisconnect(data) {
  // Run _onTransportError_ callback on every client transaction using _transport_.
  var client_transactions = ['nict', 'ict', 'nist', 'ist'];
  for (var type of client_transactions) {
    for (var id in this._transactions[type]) {
      if (Object.prototype.hasOwnProperty.call(this._transactions[type], id)) {
        this._transactions[type][id].onTransportError();
      }
    }
  }
  this.emit('disconnected', data);

  // Call registrator _onTransportClosed_.
  this._registrator.onTransportClosed();
  if (this._status !== C.STATUS_USER_CLOSED) {
    this._status = C.STATUS_NOT_READY;
    this._error = C.NETWORK_ERROR;
  }
}

// Transport data event.
function onTransportData(data) {
  var transport = data.transport;
  var message = data.message;
  message = Parser.parseMessage(message, this);
  if (!message) {
    return;
  }
  if (this._status === C.STATUS_USER_CLOSED && message instanceof SIPMessage.IncomingRequest) {
    return;
  }

  // Do some sanity check.
  if (!sanityCheck(message, this, transport)) {
    return;
  }
  if (message instanceof SIPMessage.IncomingRequest) {
    message.transport = transport;
    this.receiveRequest(message);
  } else if (message instanceof SIPMessage.IncomingResponse) {
    /* Unike stated in 18.1.2, if a response does not match
    * any transaction, it is discarded here and no passed to the core
    * in order to be discarded there.
    */

    var transaction;
    switch (message.method) {
      case CRTC_C.INVITE:
        transaction = this._transactions.ict[message.via_branch];
        if (transaction) {
          transaction.receiveResponse(message);
        }
        break;
      case CRTC_C.ACK:
        // Just in case ;-).
        break;
      default:
        transaction = this._transactions.nict[message.via_branch];
        if (transaction) {
          transaction.receiveResponse(message);
        }
        break;
    }
  }
}